package at.gaderman.serverFest.fests.arenas;

import at.gaderman.serverFest.fests.game.FestGame;
import org.bukkit.Location;

import java.util.Set;

/**
 * A resolved arena layout, generated by an {@link ArenaDefinition}, holds at least the origin position and the chunks required for the fest.
 * The {@link ArenaManager} then uses the resolved chunks to pre-generate terrain slowly.
 * The final fest instance may have additional properties resolved from this ArenaLayout which it can make use of.
 */
public interface ArenaLayout {
    Location origin();
    Set<FestGame.ChunkPos> chunks();
}
